INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) VALUES ('chunk_62cc7858576f329515472838','wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md',10,'Seite 11','Tipps und Tricks zur Bedienung von pathOS, bekannte Fehler und

Workarounds – Stand: 23.03.2026

- TPN Importe + Fallstricke und Tricks

- Bitte achten Sie darauf, dass unter Zugcharakteristik „PZB90“ ausgewählt ist

- Baukorridor: Wenn Sie aus einem Entwurf den Regelzug erstellt und abgeschickt haben, erstellen Sie aus dem offenen Vorgang die

Bauzeitscheibe. Dann können Sie dort den Baukorridor eingeben.

- Arbeiten mit Entwürfen und Speichern, Bezeichnungen etc.

- Entwürfe, die fortgesetzt werden, bleiben nach Abschicken unter alter Bezeichnung im Reiter Entwürfe gespeichert. Wenn man die

Bezeichnung ändert und erneut als Entwurf speichert, verdoppelt sich der Entwurf. In beiden Fällen kann der Entwurf manuell

gelöscht werden.

- Ein neuer Entwurf, der unter einer bereits benutzten Vorgangsbezeichnung gespeichert wird, überschreibt ungefragt den bisherigen

Vorgang. Wenn der alte Entwurf beibehalten werden soll, vergeben Sie bitte eine neue Vorgangsbezeichnung

- Im Kalender wird zuerst das aktuelle Fahrplanjahr (2026) angezeigt – dieses muss manuell mit Klick auf den Pfeil rechts auf 2027

angepasst werden (sowohl Trassenanmeldung als auch Case Reference Objekt)

- Im Kalender Verkehrszeitraum per Maus auswählen

- Aktuell haben wir Einzelfälle, bei denen Entwürfe nicht gespeichert werden können – wenn Sie das haben, gerne eine Information

dazu mit Screenshot und Details, wir sind hier noch in der Fehleranalyse (und es können mehrere Ursachen sein)

- Verbesserungsvorschläge werden aufgenommen

- Verbesserung der Filterlogik, z.B. Ausblenden von Vorgängen mit dem Status Zurückweisung, Speichern der Filtereinstellungen

- Spaltenbreite ändern

DB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 11',243,'{"canonical_url":null,"normalized_sha256":"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692","page":11,"source_id":"src_3144bf05b4098f1b3f75","source_sha256":"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008","source_version_id":"sv_44fe2d3163612d9c0a1e9803"}','33ea852cc97cd78e56d5a20b95f06d5c828dffdb8cd966568779e4fc3d494d20');

