INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) VALUES ('chunk_89d73cfe694d9803f75da3cb','wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md',11,'Seite 12','Informationen zur Vorbereitung auf die Bestellung im

Gelegenheitsverkehr in pathOS

Bedienung von pathOS & Fachlichkeit

• Auch wenn aktuell noch im Netzfahrplan bestellt wird, gab es den Wunsch, auch das Thema GelV bereits zu adressieren.

Generell unterscheidet sich die Bedienung von pathOS im GelV NICHT vom Netzfahrplan, das Webportal erkennt

automatisch, dass es eine Bestellung im GelV ist. Alle Funktionalitäten wie z.B. Eingabe von Produktausprägungen, Laufweg,

Zugcharakteristik, Identifikatoren und Verkehrszeitraum sind gleich

• Es müssen insbesondere dieselben Angaben getätigt werden, die auch im Netzfahrplan nötig sind, zusätzliche Felder gibt es

im GelV nicht

Schulungen

• Im Kern sind alle Schulungsmaterialien für den GelV ebenfalls zu verwenden (und schon so aufgebaut worden)

• Selbstverständlich wird es auch in Begleitung des GelV weitere Schulungstermine geben: Die Vertiefungsworkshops sind

bereits veröffentlicht (Juli, September, Dezember), weitere individuelle Termine werden sukzessive angeboten

• Zusätzlich werden für einzelne neue und GelV-spezielle Themen dann bei Bedarf neue Erklärvideos erstellt und die Themen

im Handbuch aufgenommen

DB InfraGO AG | TAF/TAP TSI-Dialog am 26.03.2026 12',167,'{"canonical_url":null,"normalized_sha256":"8780ed51602e70efd5973305ad8a6b6b005a0e7c7edeadbb99fe66d11fa65692","page":12,"source_id":"src_3144bf05b4098f1b3f75","source_sha256":"44fe2d3163612d9c0a1e98037270d0a8bb34b94b75bed09d755c2fcc750d4008","source_version_id":"sv_44fe2d3163612d9c0a1e9803"}','8f20b3e7a4d54bdd964057a3ebfd3dc8c14c4bb6f7e49a7eb461a365aa49ee0f');

