INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) VALUES ('chunk_31aaa3ecf37660fb34dafdce','wiki/sources/taf-tap-tsi-dialog-26-maerz-2026-terminunterlage-data.md',12,'Seite 13','Schulungsmaterial aktualisiert und umfangreich online: zu

verwenden für GelV und Netzfahrplananmeldephase

Web-based-Trainings (WBT): Der ideale Einstieg

• 9 Grundlagen WBT in den Lerneinheiten 1-4 – Basics zur Bedienung der neuen Oberfläche

• 2 komplexe WBT mit Anwendungsfällen im SGV und SPV und vielen Sonderfällen – Beide sehr empfehlenswert!

Erklärvideos: Vertiefung einzelner Anwendungsfälle

• Mittlerweile knapp 60 Videos veröffentlicht – aufgeteilt in Anwendung in pathOS (Grundlagen und Vertiefung) sowie

TAF/TAP TSI (Grundlagen und Vertiefung)

• Bei Bedarf Ergänzung zusätzliche Themen, ganz aktuell hinzugefügt: „Durchführendes EVU“, „Mehrfachtraktionen“

Handbuch: Umfangreiches Detailwissen und Nachschlagewerk

• Handbuch aktuell in Version 1.01 mit Stand 13.03.26 veröffentlicht – Überarbeitung bei Bedarf kurzfristig möglich,

Änderungshistorie im Dokument verfügbar

Vertiefungsworkshops: Anwendungsbeispiele gemeinsam mit Experten durchgehen

• Zusätzlich auch für den weiteren Jahresverlauf schon terminiert sind 3stündige Vertiefungsworkshop unseres

Trainingsdienstleisters – Termine bis April buchbar, weitere Termine für Juli, September veröffentlicht (Termine für

den Fahrplanwechsel folgen für Dezember)

